"use client";

import { useState, useEffect } from "react";
import { DndContext, pointerWithin, DragEndEvent, PointerSensor, useSensor, useSensors } from "@dnd-kit/core";
import ScrumColumn from "./ScrumColumn";
import { ChevronDown, LayoutDashboard, Search } from "lucide-react";

export default function ScrumBoard() {
  const [columns, setColumns] = useState<any>({ backlog: [], sprint: [], todo: [], progress: [], done: [] });
  const [activeSprint, setActiveSprint] = useState("Sprint 1");
  const sprints = ["Sprint 1", "Sprint 2", "Sprint 3", "Sprint 4"];

  useEffect(() => {
    fetch(`/api/scrumboard/items?sprint=${activeSprint}`)
      .then(res => res.json())
      .then(data => setColumns(data));
  }, [activeSprint]);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 8 } }));

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over) return;
    const activeId = active.id as string;
    const overId = over.id as string;

    const findColumn = (id: string) => {
      if (columns[id]) return id;
      return Object.keys(columns).find(key => columns[key].includes(id));
    };

    const sourceCol = findColumn(activeId);
    const destCol = findColumn(overId) || overId;

    if (!sourceCol || !destCol || sourceCol === destCol) return;

    setColumns((prev: any) => {
      const sourceItems = [...prev[sourceCol]];
      const destItems = [...prev[destCol]];
      const activeIndex = sourceItems.indexOf(activeId);
      if (activeIndex !== -1) {
        sourceItems.splice(activeIndex, 1);
        destItems.push(activeId);
      }
      return { ...prev, [sourceCol]: sourceItems, [destCol]: destItems };
    });

    await fetch("/api/scrumboard/items", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: activeId, newColumnId: destCol }),
    });
  };

  return (
    <div className="bg-[#0B0C10] h-screen w-full flex flex-col overflow-hidden font-sans selection:bg-blue-500/30">
      {/* HEADER: Daha ince ve profesyonel */}
      <header className="h-20 px-8 flex items-center justify-between border-b border-white/5 bg-[#0F111A]/80 backdrop-blur-xl z-20">
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/20">
              <LayoutDashboard size={20} className="text-white" />
            </div>
            <h1 className="text-white font-bold tracking-tight text-lg">ScrumFlow</h1>
          </div>
          <div className="h-6 w-[1px] bg-white/10 mx-2" />
          <div className="relative group hidden md:block">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={14} />
            <input placeholder="Zoek taken..." className="bg-white/5 border border-white/5 rounded-lg py-1.5 pl-9 pr-4 text-xs text-white outline-none focus:border-blue-500/50 w-64 transition-all" />
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="relative cursor-pointer group">
            <select 
              value={activeSprint}
              onChange={(e) => setActiveSprint(e.target.value)}
              className="appearance-none bg-blue-600/10 hover:bg-blue-600/20 text-blue-400 text-xs font-bold py-2 pl-4 pr-10 rounded-lg border border-blue-500/20 outline-none cursor-pointer transition-all"
            >
              {sprints.map(s => <option key={s} value={s} className="bg-[#1A1D29] text-white">{s}</option>)}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-blue-400 pointer-events-none" size={14} />
          </div>
        </div>
      </header>

      {/* BOARD: Tüm sütunları sığdırmaya çalışan yapı */}
      <main className="flex-1 overflow-x-auto overflow-y-hidden bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-blue-900/10 via-transparent to-transparent">
        <DndContext sensors={sensors} collisionDetection={pointerWithin} onDragEnd={handleDragEnd}>
          <div className="flex gap-5 p-6 h-full min-w-max">
            <ScrumColumn id="backlog" title="Backlog" items={columns.backlog} setColumns={setColumns} activeSprint={activeSprint} />
            <ScrumColumn id="sprint" title="Sprint" items={columns.sprint} setColumns={setColumns} activeSprint={activeSprint} />
            <ScrumColumn id="todo" title="Te doen" items={columns.todo} setColumns={setColumns} activeSprint={activeSprint} />
            <ScrumColumn id="progress" title="Bezig" items={columns.progress} setColumns={setColumns} activeSprint={activeSprint} />
            <ScrumColumn id="done" title="Klaar" items={columns.done} setColumns={setColumns} activeSprint={activeSprint} />
          </div>
        </DndContext>
      </main>
    </div>
  );
}