"use client";

import { useState, useEffect } from "react";
import { DndContext, pointerWithin, DragEndEvent, PointerSensor, useSensor, useSensors } from "@dnd-kit/core";
import ScrumColumn from "./ScrumColumn";
import { ChevronDown, LayoutDashboard } from "lucide-react";

export default function ScrumBoard() {
  const [columns, setColumns] = useState<any>({ backlog: [], sprint: [], todo: [], progress: [], done: [] });
  const [activeSprint, setActiveSprint] = useState("Sprint 1");
  const sprints = ["Sprint 1", "Sprint 2", "Sprint 3", "Sprint 4"];

  useEffect(() => {
    fetch(`/api/scrumboard/items?sprint=${activeSprint}`)
      .then(res => res.json())
      .then(data => setColumns(data));
  }, [activeSprint]);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 8 } }));

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over) return;
    const activeId = active.id as string;
    const overId = over.id as string;

    const findColumn = (id: string) => {
      if (columns[id]) return id;
      return Object.keys(columns).find(key => columns[key].includes(id));
    };

    const sourceCol = findColumn(activeId);
    const destCol = findColumn(overId) || overId;

    if (!sourceCol || !destCol || sourceCol === destCol) return;

    setColumns((prev: any) => {
      const sourceItems = [...prev[sourceCol]];
      const destItems = [...prev[destCol]];
      const activeIndex = sourceItems.indexOf(activeId);
      if (activeIndex !== -1) {
        sourceItems.splice(activeIndex, 1);
        destItems.push(activeId);
      }
      return { ...prev, [sourceCol]: sourceItems, [destCol]: destItems };
    });

    await fetch("/api/scrumboard/items", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: activeId, newColumnId: destCol }),
    });
  };

  return (
    <div className="bg-[#0F111A] min-h-screen w-full flex flex-col overflow-hidden">
      {/* Header */}
      <div className="p-8 flex justify-between items-center bg-[#14161F]/50 border-b border-white/5 backdrop-blur-md">
        <div className="flex items-center gap-4">
          <div className="bg-blue-600 p-3 rounded-2xl shadow-lg shadow-blue-600/30">
            <LayoutDashboard size={24} className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">Project Board</h1>
            <p className="text-slate-500 text-xs font-medium">{activeSprint} Overzicht</p>
          </div>
        </div>

        <div className="relative">
          <select 
            value={activeSprint}
            onChange={(e) => setActiveSprint(e.target.value)}
            className="appearance-none bg-[#1A1D29] text-white text-sm font-bold py-3 pl-6 pr-12 rounded-2xl border border-white/10 outline-none focus:border-blue-500/50 cursor-pointer hover:bg-[#232736] transition-all"
          >
            {sprints.map(s => <option key={s} value={s}>{s}</option>)}
          </select>
          <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={18} />
        </div>
      </div>

      {/* Board Area */}
      <DndContext sensors={sensors} collisionDetection={pointerWithin} onDragEnd={handleDragEnd}>
        <div className="flex-1 overflow-x-auto overflow-y-hidden scrollbar-thin scrollbar-thumb-white/10 scrollbar-track-transparent">
          <div className="flex gap-8 p-8 min-w-max h-full items-start">
            <ScrumColumn id="backlog" title="📋 Backlog" items={columns.backlog} setColumns={setColumns} activeSprint={activeSprint} />
            <ScrumColumn id="sprint" title="📝 Sprint" items={columns.sprint} setColumns={setColumns} activeSprint={activeSprint} />
            <ScrumColumn id="todo" title="🟡 Te doen" items={columns.todo} setColumns={setColumns} activeSprint={activeSprint} />
            <ScrumColumn id="progress" title="🔵 In behandeling" items={columns.progress} setColumns={setColumns} activeSprint={activeSprint} />
            <ScrumColumn id="done" title="✅ Voltooid" items={columns.done} setColumns={setColumns} activeSprint={activeSprint} />
          </div>
        </div>
      </DndContext>
    </div>
  );
}